require(script.Parent.Parent.Parent.Parent.Parent:WaitForChild(".luau-aliases"):WaitForChild("@jsdotlua"):WaitForChild("es7-types"))
local map = require(script.Parent:WaitForChild("map"))
return function(list, value: string?)
	if #list == 0 then
		return ""
	end

	local v = map(list, function(p)
		return (tostring(p))
	end)
	return table.concat(v, value or ",")
end